import * as THREE from 'three/webgpu';
import { texture, uv, uniform, color, mix, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-2';
  group.position.set(3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const imgTex = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  imgTex.colorSpace = THREE.SRGBColorSpace;

  const hoverAmount = uniform(0);
  const accentColor = color(0xff2a38);
  const inkColor = color(0x16161d);

  const baseTex = texture(imgTex, uv());
  const edgeMix = mix(baseTex, vec4(accentColor, 1.0), hoverAmount.mul(0.12));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = edgeMix;
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // accent edge frame (thin border plane behind, scales with hover)
  const edgeGeo = new THREE.PlaneGeometry(width + 0.04, height + 0.04);
  const edgeMat = new THREE.MeshBasicNodeMaterial();
  edgeMat.colorNode = vec4(accentColor, 1.0);
  edgeMat.transparent = true;
  edgeMat.opacity = 0.0;
  const edgeMesh = new THREE.Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.001;
  group.add(edgeMesh);

  // stock badge placeholder (simple plane, updated via data binding)
  const badgeGeo = new THREE.PlaneGeometry(0.28, 0.1);
  const badgeMat = new THREE.MeshBasicNodeMaterial();
  badgeMat.colorNode = vec4(inkColor, 1.0);
  badgeMat.transparent = true;
  const badgeMesh = new THREE.Mesh(badgeGeo, badgeMat);
  badgeMesh.position.set(width / 2 - 0.18, height / 2 - 0.08, 0.001);
  badgeMesh.visible = false;
  group.add(badgeMesh);

  let stockBadgeState = null;
  function applyStockStatus(inStock) {
    stockBadgeState = inStock;
    badgeMesh.visible = true;
    badgeMat.colorNode = vec4(inStock ? color(0x2ecc71) : color(0xff2a38), 1.0);
  }

  if (ctx.trpc && ctx.trpc.inventory && ctx.trpc.inventory.status) {
    try {
      const result = ctx.trpc.inventory.status.query({ itemId: 'journal-card-2' });
      if (result && typeof result.then === 'function') {
        result.then((res) => {
          if (res && typeof res.inStock === 'boolean') applyStockStatus(res.inStock);
        }).catch(() => {});
      } else if (result && typeof result.inStock === 'boolean') {
        applyStockStatus(result.inStock);
      }
    } catch (e) {
      // no-op, data binding optional
    }
  }

  const timelines = [];
  const baseY = group.position.y;

  function onHoverIn() {
    edgeMat.opacity = 0.9;
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(hoverAmount, { value: 1, duration: 0.7, ease: 'power3.out' }, 0);
    timelines.push(tl);
  }

  function onHoverOut() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(hoverAmount, { value: 0, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(edgeMat, { opacity: 0, duration: 0.7, ease: 'power3.out' }, 0);
    timelines.push(tl);
  }

  function onPress() {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'back.out' });
    timelines.push(tl);

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { id: 'hub-journal-card-2' });
    }
  }

  group.userData.handlers = {
    onPointerOver: onHoverIn,
    onPointerOut: onHoverOut,
    onPointerDown: onPress,
    onClick: onPress,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    geometry.dispose();
    material.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    badgeGeo.dispose();
    badgeMat.dispose();
    if (imgTex) imgTex.dispose();
  };

  return group;
}
